const PLANNER_FREE_DAY_BUCKETS = [
  { key: "coast", kinds: ["beach", "sunset", "beachclub"] },
  { key: "food", kinds: ["restaurant", "cafe"] },
  { key: "explore", kinds: ["temple", "scenic", "waterfall", "walk", "culture"] },
];

