function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

// Article copy may use **bold** to highlight the numbers and names readers scan
// for. Escape first, then introduce our own tags, so nothing in the source text
// can inject markup.
function renderRichText(value) {
  return escapeHtml(String(value ?? ""))
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    // [label](/internal/path) — internal paths only, so copy cannot inject an
    // external or javascript: destination.
    .replace(/\[([^\]]+)\]\((\/[a-zA-Z0-9\-_\/#]*)\)/g, '<a href="$2">$1</a>');
}

// Structured data must be plain text — strip the ** markers instead of rendering them.
function stripRichText(value) {
  return String(value ?? "")
    .replace(/\*\*(.+?)\*\*/g, "$1")
    .replace(/\[([^\]]+)\]\(\/[^)]*\)/g, "$1");
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// Real, per-tour photos fetched from Pexels (scripts/fetch-tour-photos.mjs).
// When present they replace the duplicated catalog images and carry an SEO alt.
const TOUR_REAL_IMAGES = (() => {
  const manifestPath = path.join(projectRoot, "images", "tours-real", "_manifest.json");
  if (!fs.existsSync(manifestPath)) return {};
  try {
    return JSON.parse(fs.readFileSync(manifestPath, "utf8"));
  } catch {
    return {};
  }
})();

/* Видео вместо фотографии на герое тура.

   Кладётся руками в videos/tours/<слуг>.mp4 плюс постер -poster.jpg рядом.
   Есть файл — герой становится видео, нет — остаётся фото. Никаких правок
   кода на каждый тур.

   Фон-картинка при этом НЕ убирается: она рисуется мгновенно и служит
   подложкой, поверх которой видео проявляется, когда сможет играть. Так нет
   ни пустого кадра, ни скачка вёрстки, а у кого видео не запустится —
   увидит ровно то же, что и раньше. */
function tourHeroVideo(tour) {
  const slug = tour && tour.slug;
  if (!slug) return null;
  const rel = `/videos/tours/${slug}.mp4`;
  if (!fs.existsSync(path.join(projectRoot, "videos", "tours", `${slug}.mp4`))) return null;
  const posterRel = `/videos/tours/${slug}-poster.jpg`;
  const hasPoster = fs.existsSync(path.join(projectRoot, "videos", "tours", `${slug}-poster.jpg`));
  return { src: rel, poster: hasPoster ? posterRel : null, position: HERO_VIDEO_POSITION[slug] || null };
}

/* Вертикальное положение видимой полосы видео.

   На десктопе рамка героя широкая (соотношение 2,02), и вертикальное видео
   показывается узким горизонтальным срезом — у ролика с китовой акулой
   видно всего 28% высоты кадра, и сама акула в этот срез не попадала:
   зритель видел пустую воду. Сдвигаем полосу вниз, на сюжет.

   Значение подбирается глазами под конкретный ролик. Горизонтальным видео
   это не нужно — они и так закрывают широкую рамку почти целиком. */
const HERO_VIDEO_POSITION = {
  "sumbawa-whale-shark-snorkeling-trip": "50% 62%",
  /* Манта по ходу ролика поднимается к поверхности: её центр смещается с
     53 процентов высоты кадра в начале до 27 в конце, в среднем около 36.
     При центровке по умолчанию она видна на десктопе только первые пару
     секунд, дальше уплывает из полосы. */
  "nusa-penida-manta-rays-point": "50% 36%",
  /* Колонна джипов снята вертикально: в широкую рамку героя попадает 28%
     высоты кадра. По центру видны только колёса и дорога, при 35% срезает
     поднятые руки пассажиров. На 42% в полосу целиком входят и джип, и люди
     на всём протяжении ролика — проверено по кадрам на 2, 6, 10 и 14 секунде. */
  "mount-batur-sunrise-jeep-tour": "50% 42%",
  /* Ролик с машинами снят на телефон вертикально, с поворотом в метаданных.
     На 30% в полосу попадают крыши, на 60% — асфальт и читаемый номер машины
     поставщика. На 45% в кадре сами машины на всём протяжении. */
  "private-car-with-driver-bali": "50% 45%",
};

function renderHeroVideoMarkup(video, altText) {
  if (!video) return "";
  /* src через data-: браузер не трогает файл, пока страница не догрузилась.
     Иначе полтора мегабайта конкурируют с LCP на мобильном, где у нас три
     четверти кликов. Запуск, отказ по экономии трафика и по «уменьшить
     движение» — в скрипте ниже. */
  const position = video.position ? ` style="object-position:${escapeHtml(video.position)}"` : "";
  return `<video class="sb-hero-video" muted loop playsinline preload="none" tabindex="-1" aria-hidden="true"${position}` +
    (video.poster ? ` poster="${escapeHtml(video.poster)}"` : "") +
    ` data-src="${escapeHtml(video.src)}"></video>`;
}

function publicImagePath(tour) {
  const real = TOUR_REAL_IMAGES[tour.slug];
  if (real?.file) return `/images/tours-real/${real.file}`;
  return `/images/bali-tours/${tour.slug}${path.extname(tour.image).toLowerCase()}`;
}

function tourImageAlt(tour) {
  return TOUR_REAL_IMAGES[tour.slug]?.alt || tour.imageAlt || tour.title;
}

// Apply the SEO alt from the manifest to every tour, so all image references —
// catalog cards, journal cards and og:image alt — describe the real photo.
for (const t of tours) {
  const real = TOUR_REAL_IMAGES[t.slug];
  if (real?.alt) t.imageAlt = real.alt;
}

function tourLocale(tour) {
  return collapseWhitespace(tour?.locale || "en").toLowerCase();
}

