  var ABOUT_ICON_BG_IDS = ['1766431186034000001', '1766431201693000002', '1766431219359000004', '1766431153685'];
  var ABOUT_ICON_IDS = ['1721244135166', '1721244135187', '1766431213467000003', '1721244135202'];
