function buildSeoGuideArticle(guide) {
  const heroTour = tourBySlug(guide.heroTourSlug) || tours[0];
  // Список мест есть не у всякого гайда: разбор пошлины или ответ «можно ли
  // подняться без гида» — сплошной текст без ранжированных карточек. Раньше
  // такой гайд ронял сборку на .map() по undefined; теперь просто нет карточек,
  // а героем страницы становится фото опорного тура (см. heroImage ниже).
  const rankings = (guide.rankings || []).map((item, index) => ({
    ...item,
    position: index + 1,
    image: normalizeJournalImageSrc(item.imageSrc || guidePlaceImage(item.imageTitle || item.name, item.fallbackTourSlug || guide.heroTourSlug)),
  }));
  const leadPlace = rankings[0]?.name || heroTour.title;

  const resolvedOffer = guide.offer || buildGuideOfferFromRelated(guide);

  return {
    kind: "guide",
    guide: resolvedOffer && !guide.offer ? { ...guide, offer: resolvedOffer } : guide,
    tour: heroTour,
    articleType: { badge: guide.badge, navLabel: guide.navLabel, key: guide.key },
    cardTourLabel: guide.cardTourLabel,
    route: guideArticleRoute(guide),
    url: absoluteGuideArticleUrl(guide),
    title: guide.title,
    description: guide.description,
    excerpt: guide.excerpt,
    sections: guide.sections,
    faq: guide.faq,
    inlineStats: guide.inlineStats,
    rankings,
    heroImage: GUIDE_HERO_IMAGES[guide.slug]?.[0] || rankings[0]?.image || publicImagePath(heroTour),
    heroImageAlt: GUIDE_HERO_IMAGES[guide.slug]?.[1] || `${leadPlace} in Bali`,
    relatedTours: guide.relatedTourSlugs.map((slug) => tourBySlug(slug)).filter(Boolean),
    relatedGuides: relatedGuidesFor(guide),
  };
}

