function translationCacheBucket(locale = "en") {
  const cache = ensureTranslationCache();
  const key = translationLocaleCode(locale);
  if (!cache[key] || typeof cache[key] !== "object") {
    cache[key] = {};
  }
  const pinned = PINNED_TRANSLATIONS[key];
  if (pinned) Object.assign(cache[key], pinned);
  return cache[key];
}

// Имена, которые остаются как есть на всех языках: платёжные бренды, соцсети,
// аббревиатуры и названия языков в переключателе. «Visa» по-русски не «Виза»,
// а «Stripe» не «Полоска».
const NEVER_TRANSLATE = new Set([
  "WhatsApp", "Instagram", "Facebook", "YouTube", "Telegram", "TripAdvisor",
  "PayPal", "Stripe", "Visa", "Mastercard", "Amex", "Klarna", "Bitcoin",
  "Ethereum", "BitPay", "Google", "FAQ", "SiteMap", "SB",
  "English", "Русский", "Español", "Français", "中文",
  /* Имена типов schema.org. На китайской легаси-странице манты «FAQPage»
     перевелось в «常见问题Page» — такого типа не существует, и Google
     молча выбрасывает всю разметку страницы. Ошибка тихая: JSON остаётся
     валидным, ломается только смысл. */
  "FAQPage", "Question", "Answer", "WebPage", "BlogPosting", "Product",
  "BreadcrumbList", "ItemList", "TouristTrip", "TravelAgency", "Organization",
  "Person", "VideoObject", "AboutPage", "Blog",
]);

function shouldTranslateTextValue(value) {
  const text = String(value || "");
  const collapsed = collapseWhitespace(text);
  if (!collapsed) return false;
  if (/^(?:https?:)?\/\//i.test(collapsed)) return false;
  if (/^\/(?:bali|dubai|images|css|js|files)\//i.test(collapsed)) return false;
  if (NEVER_TRANSLATE.has(collapsed)) return false;
  // Пропускаем идентификаторы — слаги, имена файлов, классы. Раньше здесь
  // отсеивалось ЛЮБОЕ слово без пробелов, и вместе с «nusa-penida-west-tour»
  // мимо перевода проходили обычные подписи интерфейса: Duration, Area,
  // Format, From, Pickup — на всех четырёх языках они оставались английскими.
  // Признак идентификатора — дефис, подчёркивание, точка или цифра внутри.
  if (/^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/i.test(collapsed) && !/\s/.test(collapsed) && /[-_.\d]/.test(collapsed)) {
    return false;
  }
  return /[A-Za-z]/.test(collapsed);
}

function maskHtmlTags(fragment) {
  const tags = [];
  const masked = String(fragment || "").replace(/<[^>]+>/g, (tag) => {
    const index = tags.push(tag) - 1;
    return `𓆩SBTAG${index}𓆪`;
  });
  return { masked, tags };
}

function unmaskHtmlTags(fragment, tags = []) {
  return String(fragment || "").replace(/𓆩SBTAG(\d+)𓆪/g, (_, rawIndex) => tags[Number(rawIndex)] || "");
}

/* Точка translate_a/single неофициальная и режет по частоте: при заливке
   новой пачки статей она отдаёт 429 сотнями подряд. Раньше это молча
   превращалось в английский текст на русских страницах. Теперь три попытки
   с растущей паузой плюс минимальный интервал между запросами — медленнее,
   но сборка доходит до конца с настоящим переводом. */
const TRANSLATE_MIN_GAP_MS = 45;
let translateLastCallAt = 0;

/* Общий предел времени на переводы за одну сборку.
 *
 * Точка translate_a/single не просто медленная — она умеет подвешивать
 * соединение так, что процесс остаётся ждать TLS-сокет, которого уже нет.
 * Пер-запросный таймаут это не всегда ловит: сборка простояла так три часа,
 * напечатав первый шаг и замолчав.
 *
 * Поэтому здесь жёсткий общий бюджет. Кончился — API больше не зовём, и
 * сборка доходит до конца на том, что уже в кэше. Непереведённые строки
 * останутся английскими, счётчик их посчитает, предупреждение об этом
 * напечатается. Дальше просто запускаем сборку ещё раз: кэш пополняется
 * с каждым проходом, и рано или поздно проход отработает вчистую.
 * Лучше законченная сборка с честным отчётом, чем висящий процесс. */
/* Восемь минут — на обычную сборку, где переводится десяток новых строк.
   Догоняющий проход после простоя Google (сотни строк разом) в них не влезает,
   поэтому лимит поднимается переменной окружения: TRANSLATE_BUDGET_MIN=30. */
const TRANSLATE_BUDGET_MS = Number(process.env.TRANSLATE_BUDGET_MIN || 8) * 60 * 1000;
const translateStartedAt = Date.now();
let translateBudgetSpent = false;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/* Запасной канал перевода — официальный Cloud Translation.
 *
 * Бесплатная точка translate_a/single ушла в глухой отказ: пять запросов из
 * пяти отдают 429, и это не разрыв в лимите, а стена. Пока она закрыта, любая
 * новая строка остаётся английской, а немецкая версия сайта стоит на 35%
 * наполнения кэша против французских 100%.
 *
 * Ключ берём тот же, что уже лежит для Search Console. Если Cloud Translation
 * в проекте не включён, API отвечает 403 с текстом «has not been used in
 * project … or it is disabled» — тогда канал помечается недоступным ОДИН раз,
 * и сборка больше в него не стучится: иначе на каждую строку приходился бы
 * лишний запрос и минуты ожидания впустую.
 *
 * Включается по адресу из текста ошибки, одной кнопкой в консоли проекта. */
const CLOUD_TRANSLATE_KEY_PATH = process.env.SB_TRANSLATE_KEY
  || path.join(process.env.HOME || "", ".config", "claude-seo", "service_account.json");
let cloudTranslateState = null; // null — не пробовали, false — недоступен, объект — готов
let cloudTokenCache = { token: null, expiresAt: 0 };

async function cloudAccessToken(key) {
  if (cloudTokenCache.token && Date.now() < cloudTokenCache.expiresAt - 60_000) return cloudTokenCache.token;
  const crypto = await import("node:crypto");
  const now = Math.floor(Date.now() / 1000);
  const b64 = (obj) => Buffer.from(JSON.stringify(obj)).toString("base64url");
  const claim = `${b64({ alg: "RS256", typ: "JWT" })}.${b64({
    iss: key.client_email,
    scope: "https://www.googleapis.com/auth/cloud-platform",
    aud: "https://oauth2.googleapis.com/token",
    exp: now + 3600,
    iat: now,
  })}`;
  const signature = crypto.createSign("RSA-SHA256").update(claim).sign(key.private_key).toString("base64url");
  const response = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
      assertion: `${claim}.${signature}`,
    }),
    signal: AbortSignal.timeout(15000),
  });
  if (!response.ok) throw new Error(`token ${response.status}`);
  const data = await response.json();
  cloudTokenCache = { token: data.access_token, expiresAt: Date.now() + data.expires_in * 1000 };
  return cloudTokenCache.token;
}

async function fetchCloudTranslation(text, locale) {
  if (cloudTranslateState === false) return null;
  if (cloudTranslateState === null) {
    try {
      cloudTranslateState = JSON.parse(fs.readFileSync(CLOUD_TRANSLATE_KEY_PATH, "utf8"));
    } catch {
      cloudTranslateState = false;
      console.warn("⚠ перевод: ключа Cloud Translation нет, запасного канала не будет");
      return null;
    }
  }
  const key = cloudTranslateState;
  try {
    const token = await cloudAccessToken(key);
    const response = await fetch(
      `https://translation.googleapis.com/v3/projects/${key.project_id}:translateText`,
      {
        method: "POST",
        headers: { authorization: `Bearer ${token}`, "content-type": "application/json" },
        body: JSON.stringify({
          contents: [text],
          sourceLanguageCode: "en",
          targetLanguageCode: translationLocaleCode(locale),
          mimeType: "text/plain",
        }),
        signal: AbortSignal.timeout(20000),
      },
    );
    if (!response.ok) {
      const body = await response.text();
      cloudTranslateState = false;
      if (/has not been used in project|is disabled/.test(body)) {
        console.warn("⚠ перевод: Cloud Translation в проекте не включён — включите его, и запасной канал заработает");
      } else {
        console.warn(`⚠ перевод: Cloud Translation отвечает ${response.status}, канал отключён на эту сборку`);
      }
      return null;
    }
    const data = await response.json();
    return data?.translations?.[0]?.translatedText || null;
  } catch (error) {
    cloudTranslateState = false;
    console.warn(`⚠ перевод: Cloud Translation недоступен (${String(error.message).slice(0, 60)}), канал отключён`);
    return null;
  }
}

async function fetchGoogleTranslation(text, locale = "en", attempt = 0) {
  if (Date.now() - translateStartedAt > TRANSLATE_BUDGET_MS) {
    if (!translateBudgetSpent) {
      translateBudgetSpent = true;
      console.warn(`⚠ перевод: бюджет ${TRANSLATE_BUDGET_MS / 60000} минут исчерпан, дальше только кэш`);
    }
    throw new Error("translation budget exhausted");
  }
  const gap = TRANSLATE_MIN_GAP_MS - (Date.now() - translateLastCallAt);
  if (gap > 0) await sleep(gap);
  translateLastCallAt = Date.now();

  const url = new URL("https://translate.googleapis.com/translate_a/single");
  url.searchParams.set("client", "gtx");
  url.searchParams.set("sl", "en");
  url.searchParams.set("tl", translationLocaleCode(locale));
  url.searchParams.set("dt", "t");
  url.searchParams.set("q", text);

  let response;
  try {
    /* Таймаут обязателен. Без него зависший коннект держит сборку вечно:
       fetch без сигнала ждёт бесконечно, и генератор простоял так 14 часов,
       напечатав первый шаг и замолчав. Пятнадцати секунд хватает с запасом —
       обычный ответ приходит за десятые доли. */
    response = await fetch(url, {
      headers: { accept: "application/json,text/plain,*/*" },
      signal: AbortSignal.timeout(15000),
    });
  } catch (error) {
    if (attempt < 1) { await sleep(1200); return fetchGoogleTranslation(text, locale, attempt + 1); }
    const viaCloud = await fetchCloudTranslation(text, locale);
    if (viaCloud) return viaCloud;
    throw error;
  }
  if (!response.ok) {
    /* 429 и 5xx лечатся ожиданием, 4xx кроме 429 — нет. */
    if ((response.status === 429 || response.status >= 500) && attempt < 1) {
      await sleep(2000);
      return fetchGoogleTranslation(text, locale, attempt + 1);
    }
    const viaCloud = await fetchCloudTranslation(text, locale);
    if (viaCloud) return viaCloud;
    throw new Error(`Translation request failed with ${response.status}`);
  }

  const payload = JSON.parse(await response.text());
  return Array.isArray(payload?.[0]) ? payload[0].map((item) => item?.[0] || "").join("") : text;
}

let translationFailures = 0;

async function translateTextMap(texts, locale = "en", options = {}) {
  const { richText = false, glossary = null } = options;
  const bucket = translationCacheBucket(locale);
  const sources = Array.from(new Set((texts || []).filter(shouldTranslateTextValue)));
  const translated = new Map();
  const pending = [];
  const prepared = new Map();

  for (const source of sources) {
    if (bucket[source]) {
      translated.set(source, bucket[source]);
      continue;
    }

    const preparedValue = richText ? maskHtmlTags(source) : { masked: String(source), tags: [] };
    prepared.set(source, preparedValue);
    pending.push(source);
  }

  /* Выгрузка строк вместо перевода.
  
     Кэш переводов ключуется целой исходной строкой, и заполнить его можно не
     только ответом Google. Когда точка в отказе — а в августе 2026 она ушла в
     429 на полтора суток, — строки переводятся вручную и вписываются в кэш.
     Но угадать их нельзя: сюда приходят уже нарезанные сегменты, и ключ должен
     совпасть с ними побайтово.
  
     TRANSLATE_DUMP=путь пишет каждый непереведённый сегмент в JSONL и ничего не
     запрашивает. Строки при этом остаются английскими, поэтому такая сборка
     годится только для выгрузки — деплоить её нельзя. */
  if (process.env.TRANSLATE_DUMP && pending.length) {
    const lines = pending.map((source) => JSON.stringify({
      locale,
      richText,
      masked: prepared.get(source)?.masked || source,
      source,
    })).join("\n");
    fs.appendFileSync(process.env.TRANSLATE_DUMP, lines + "\n");
    for (const source of pending) translated.set(source, source);
    return translated;
  }

  const separator = "\n[[SBXSEP]]\n";
  const maxChunkLength = 4500;
  let chunk = [];
  let chunkLength = 0;

  const flushChunk = async () => {
    if (!chunk.length) return;

    const joined = chunk.map((source) => prepared.get(source)?.masked || source).join(separator);
    let translatedPieces = [];

    try {
      const translatedJoined = await fetchGoogleTranslation(joined, locale);
      translatedPieces = translatedJoined.split("[[SBXSEP]]");
    } catch {
      translatedPieces = [];
    }

    if (translatedPieces.length !== chunk.length) {
      for (const source of chunk) {
        const preparedValue = prepared.get(source) || { masked: source, tags: [] };
        try {
          const singleTranslation = await fetchGoogleTranslation(preparedValue.masked, locale);
          const finalText = richText ? unmaskHtmlTags(singleTranslation, preparedValue.tags) : singleTranslation;
          bucket[source] = finalText;
          translated.set(source, finalText);
          translationCacheDirty = true;
        } catch {
          /* НЕ пишем исходник в кэш. Раньше здесь стояло bucket[source] = source,
             и это отравляло кэш навсегда: неофициальная точка translate_a/single
             режет по частоте, при сбое английская строка ложилась как «перевод»,
             а следующая сборка видела запись и больше не пыталась. Так на сайте
             копился английский текст на русских и французских страницах —
             2556 записей к августу 2026. Теперь при сбое строка остаётся
             непереведённой в этой сборке и будет запрошена в следующей. */
          translated.set(source, source);
          translationFailures += 1;
        }
      }
    } else {
      chunk.forEach((source, index) => {
        const preparedValue = prepared.get(source) || { tags: [] };
        const piece = translatedPieces[index] ?? source;
        const finalText = richText ? unmaskHtmlTags(piece.trim(), preparedValue.tags) : piece.trim();
        bucket[source] = finalText;
        translated.set(source, finalText);
      });
      translationCacheDirty = true;
    }

    chunk = [];
    chunkLength = 0;
  };

  for (const source of pending) {
    const preparedValue = prepared.get(source)?.masked || source;
    const nextLength = chunkLength + preparedValue.length + separator.length;
    if (chunk.length && nextLength > maxChunkLength) {
      await flushChunk();
    }
    chunk.push(source);
    chunkLength += preparedValue.length + separator.length;
  }

  await flushChunk();

  for (const source of sources) {
    if (!translated.has(source)) {
      translated.set(source, bucket[source] || source);
    }
  }

  // "SB Excursions" is a brand name — machine translation localizes it
  // ("СБ Экскурсии", "SB Excursiones", …). Restore it everywhere, including
  // values that came straight from the cache.
  for (const [source, value] of translated) {
    const branded = normalizeBrandName(value);
    translated.set(source,
      glossary === "surf" ? fixSurfGlossary(branded, locale)
      : glossary === "places" ? fixPlacesGlossary(branded, locale)
      : branded);
  }

  return translated;
}

const BRAND_NAME = "SB Excursions";

function normalizeBrandName(text) {
  if (!text) return text;
  return String(text)
    .replace(/(?:СБ|SB)\s*[-–—]?\s*Экскурси[а-яё]*/giu, BRAND_NAME)
    .replace(/SB\s*[-–—]?\s*(?:Excursiones|Excursões|Escursioni)/giu, BRAND_NAME)
    /* Немецкий переводит и само слово, и дефис приклеивает: «SB-Ausflüge»
       встретилось 500 раз на первой же волне. Бренд не переводится. */
    .replace(/SB\s*[-–—]?\s*(?:Ausflüge|Ausfluege|Exkursionen|Touren|Reisen)/giu, BRAND_NAME)
    .replace(/(?:Excursiones|Excursões|Escursioni|Excursions)\s+(?:de|del|di)\s+SB/giu, BRAND_NAME)
    .replace(/SB\s*(?:短途旅行|游览|旅游|远足|观光)/gu, BRAND_NAME);
}

/* Сёрф-глоссарий: чиним то, что Google Translate портит системно.

   Две беды, обе видны только на сёрф-статьях:

   1. НАЗВАНИЯ СПОТОВ переводятся как нарицательные. Dreamland становится
      «Страной грёз», Green Bowl — «Зелёной чашей», Impossibles —
      «Невозможным». Причём непоследовательно: в одном и том же языке рядом
      стоят Dreamland и «Страна грез». Транслитерация (Улувату, Чангу,
      Паданг-Паданг) — это нормально и её мы не трогаем; чиним только
      превращение имени в обычное слово.

   2. SURF BREAK — «перерыв», «pause», «descanso». Для сёрфера это
      мгновенный сигнал, что текст писала машина.

   NEVER_TRANSLATE здесь не помогает: он сравнивает значение целиком, а
   названия стоят внутри предложений.

   ОБЛАСТЬ ДЕЙСТВИЯ. «Храмы», «площадка» и «перерыв» — нормальные слова на
   страницах про храмы, детские площадки и расписание, поэтому глоссарий
   включается только на статьях сёрф-кластера, по адресу страницы
   (SURF_GLOSSARY_ROUTES). Пробовали сторож по содержимому сегмента — не
   работает: сегменты короткие, в «Страна грез — единственный перерыв с
   песчаным дном» нет ни одного сёрф-слова. */

const SURF_GLOSSARY = {
  /* Две ловушки JavaScript, на которых глоссарий промахнулся дважды:

     1. \w — только латиница, поэтому «Зелен\w*» не находит «Зеленая».
     2. \b определяется через тот же \w, поэтому «\bперерыв» вообще никогда
        не срабатывает: между пробелом и «п» границы слова нет.

     Отсюда явные классы [а-яё] и явные просмотры вместо \b. */
  ru: [
    [/Стран[аеуы]\s+гр[её]з/giu, "Dreamland"],
    [/Зел[её]н[а-яё]*\s+чаш[а-яё]*|Грин\s+Боул[а-яё]*/giu, "Green Bowl"],
    [/Гоночн[а-яё]*\s+трасс[а-яё]*|Рейстрек[а-яё]*|Ипподром[а-яё]*/giu, "Racetrack"],
    [/Кораблекрушени[а-яё]*/giu, "Shipwrecks"],
    [/Игров[а-яё]*\s+площадк[а-яё]*/giu, "Playgrounds"],
    [/Внешн[а-яё]*\s+угол|Внешнего\s+угла|Внешнему\s+углу|Аутсайд\s+Корнер[а-яё]*/giu, "Outside Corner"],
    [/(?<![а-яёА-ЯЁ])Рваные(?![а-яёА-ЯЁ])/gu, "Lacerations"],
    /* Google местами пишет имя спота со строчной: «Бингин и невозможное».
       Наречие «невозможно» при этом законно («волну невозможно создать»),
       поэтому ловим только формы с окончанием прилагательного. */
    [/(?<![а-яёА-ЯЁ])[Нн]евозможн(?:ое|ые|ых|ым|ыми|ом)(?![а-яёА-ЯЁ])/gu, "Impossibles"],
    [/Б[эе]би[\s-]Паданг[а-яё]*|Детск[а-яё]*\s+Паданг[а-яё]*/giu, "Baby Padang"],
    [/Темплс[а-яё]*/giu, "Temples"],
    /* Секции Улувату с большой буквы — имена, а не слова. Без флага i,
       чтобы «пик сезона» и «храм Улувату» со строчной остались как есть. */
    [/(?<![а-яёА-ЯЁ])Храм(?:ы|ов|ам|ами|ах)(?![а-яёА-ЯЁ])/gu, "Temples"],
    /* break как сёрф-термин: в сёрф-статье «перерыв» — всегда ошибка.
       «Перерыв» и «спот» — оба мужского рода с твёрдой основой, поэтому
       окончание переносим как есть: перерывов -> спотов, перерыве -> споте. */
    [/(?<![а-яёА-ЯЁ])перерыв([а-яё]*)/giu, "спот$1"],
    /* swell: «набухание» — среднего рода, как и «волнение», поэтому
       прилагательные вокруг остаются согласованными. «Свелл» мужского рода
       и ломал бы «большее необработанное …». */
    [/(?<![а-яёА-ЯЁ])набухани([ея][а-яё]*)/giu, "волнени$1"],
    [/(?<![а-яёА-ЯЁ])прорывается/giu, "работает"],
    [/(?<![а-яёА-ЯЁ])прорываются/giu, "работают"],
  ],
  /* Род подбираем под исходное слово, иначе ломаются артикли и согласование:
     descanso и spot мужского рода, ruptura и ola — женского; во французском
     pause женского, поэтому не spot (муж.), а vague (жен.). */
  es: [
    [/Pa[íi]s\s+de\s+los\s+sue[ñn]os|Tierra\s+de\s+(?:los\s+)?sue[ñn]os/giu, "Dreamland"],
    [/Taz[óo]n\s+verde|Cuenco\s+verde/giu, "Green Bowl"],
    [/Pista\s+de\s+carreras/giu, "Racetrack"],
    [/\bNaufragios\b/gu, "Shipwrecks"],
    [/\bdescansos\b/giu, "spots"],
    [/\bdescanso\b/giu, "spot"],
    [/\brupturas\b/giu, "olas"],
    [/\bruptura\b/giu, "ola"],
    [/\bhinchaz[óo]n\b/giu, "marejada"],
  ],
  fr: [
    [/Pays\s+des\s+r[êe]ves/giu, "Dreamland"],
    [/Bol\s+vert/giu, "Green Bowl"],
    [/\bNaufrages\b|\b[ÉE]paves\b/gu, "Shipwrecks"],
    [/\bpauses\b/giu, "vagues"],
    [/\bpause\b/giu, "vague"],
    [/\bruptures\b/giu, "vagues"],
    [/\brupture\b/giu, "vague"],
    [/\bgonflement(?:s)?\b/giu, "houle"],
  ],
};



/* Адреса, на которых включается сёрф-глоссарий. Держим рядом с самим
   глоссарием, чтобы список не разъехался с кластером. */
const SURF_GLOSSARY_ROUTES = /\/journal\/(?:best-surf-spots-in-bali|bali-surf-spots-for-beginners|bali-surf-spots-intermediate|uluwatu-surf-guide|canggu-surf-spots|bukit-peninsula-surf-spots|east-bali-surf-spots|west-bali-surf-medewi-balian|bali-surf-season-month-by-month|bali-surf-conditions-tides-swell-wind|is-surfing-in-bali-safe|bali-surfboard-rental-and-transport|surf-lessons-bali-beginners)\b/;

/* Второй кластер: Гили и Танах-Лот. Ошибок здесь меньше — транслитерация
   сработала правильно («Гили Эйр», а не «Гили Воздух»), — но две есть:
   дайв-сайт Air Wall переводится дословно, а cidomo записывается через «с»,
   хотя индонезийское c читается как «ч». */
const PLACES_GLOSSARY_ROUTES = /\/journal\/(?:tanah-lot-temple-guide|handara-gate-bali-guide|handara-gate-vs-lempuyang-gates-of-heaven|ulun-danu-beratan-temple-guide|bedugul-highlands-guide|tanah-lot-bedugul-day-trip-route|gili-trawangan-guide|gili-air-guide|gili-meno-guide|gili-islands-fast-boat-guide|gili-islands-with-kids|gili-islands-snorkelling-turtles)\b/;

const PLACES_GLOSSARY = {
  ru: [
    /* Air Wall — имя дайв-сайта у Гили Эйр, а не описание стены. */
    [/Воздушн[а-яё]+\s+стен[а-яё]+/giu, "Air Wall"],
    /* cidomo: индонезийское c = «ч». «Сидомо» читается неправильно. */
    [/(?<![а-яёА-ЯЁ])[Сс]идомо/gu, "чидомо"],
    [/(?<![а-яёА-ЯЁ])Сидомо/gu, "Чидомо"],
  ],
  es: [
    [/Puerta de Handara/giu, "Handara Gate"],
    [/Gili Aire/giu, "Gili Air"],
  ],
  fr: [
    [/Porte de Handara/giu, "Handara Gate"],
  ],
};

function fixPlacesGlossary(text, locale) {
  if (!text) return text;
  const rules = PLACES_GLOSSARY[locale];
  if (!rules) return text;
  let value = String(text);
  for (const [pattern, replacement] of rules) value = value.replace(pattern, replacement);
  return value;
}

function fixSurfGlossary(text, locale) {
  if (!text) return text;
  const rules = SURF_GLOSSARY[locale];
  if (!rules) return text;
  let value = String(text);
  for (const [pattern, replacement] of rules) value = value.replace(pattern, replacement);
  return value;
}

/* Покрыт ли конкретный АДРЕС этим языком.

   Нужен там, где мы не знаем тип страницы заранее: переключатель языков,
   hreflang и карта сайта строятся из маршрута. Без него немецкий предлагался
   бы на всех 1400 страницах, а ссылки вели бы в 404 — и в переключателе, и,
   что хуже, в hreflang, где Google такое считает ошибкой разметки. */
function localeCoversRoute(route, locale) {
  const text = String(route || "");
  /* Статьи, временно выходящие только по-английски, отсекаем ДО проверки
     немецкого: иначе карта сайта и hreflang звали бы Google на русские и
     французские адреса, которых мы намеренно не собрали. Это третий механизм
     покрытия, и он про адрес, а не про слаг — правя один, надо править все. */
  if (locale !== "en") {
    const only = text.match(/\/bali\/[a-z-]+\/journal\/([a-z0-9-]+)$/);
    if (only && !guideHasLocale(only[1], locale)) return false;
  }
  if (locale !== "de") return true;
  /* SB_DE_FULL открывает немецкий для всех маршрутов сразу, но файлы для части
     из них никто не генерирует: легаси-гайды лежат статикой мимо генератора, а
     у тура ЮНЕСКО свой набор языков. Без этой проверки карта сайта объявляла
     семь немецких адресов, ведущих в 404 — Google звали на пустоту.
     Существование файла и есть единственный надёжный признак покрытия. */
  if (DE_FULL) {
    const guide = text.match(/\/bali\/[a-z-]+\/journal\/([a-z0-9-]+)$/);
    if (guide) return fs.existsSync(path.join(projectRoot, `bali-journal-guide-${guide[1]}-de.html`));
    const tour = text.match(/\/bali\/[a-z-]+\/tours\/([a-z0-9-]+)$/);
    if (tour) return fs.existsSync(path.join(projectRoot, `bali-tour-${tour[1]}-de.html`));
  }
  let match = text.match(/\/bali\/[a-z-]+\/tours\/([a-z0-9-]+)$/);
  if (match) return DE_FULL || DE_WAVE_TOURS.has(match[1]);
  // статья-спутник тура: /bali/xx/journal/<тур>/<тип> — немецкий их не получает
  if (/\/bali\/[a-z-]+\/journal\/[a-z0-9-]+\/[a-z0-9-]+$/.test(text)) return DE_FULL;
  match = text.match(/\/bali\/[a-z-]+\/journal\/([a-z0-9-]+)$/);
  if (match) return DE_FULL || DE_WAVE_GUIDES.has(match[1]);
  // главная, хаб журнала, about, faq, guides — немецкие версии есть у всех
  return true;
}

/* Подгонка meta description под длину выдачи.

   Английские описания пишутся под ~155 знаков, но машинный перевод
   раздувает строку на треть и больше: французские доходили до 301 знака,
   русские до 279. Google обрезает такое посреди слова многоточием — и
   ответ, ради которого описание и писалось, до читателя не доходит.

   Режем по смысловой границе, а не по буквам: сначала пробуем конец
   предложения, потом тире или двоеточие, потом запятую. Короткое, но
   целое описание читается как задуманное, а обрубок — как поломка.

   Заголовки сознательно НЕ трогаем: они короткие, и любая обрезка
   выносит из них смысл — «Sources chaudes du mont Batur : quand le bain
   en vaut la peine» схлопывалось до «Sources chaudes du mont Batur».
   Для них — ручные пины. */
const META_DESCRIPTION_LIMITS = { zh: 80, ru: 140, ja: 80, ko: 80 };

function metaDescriptionLimit(locale) {
  return META_DESCRIPTION_LIMITS[locale] || 155;
}

/* Обрезка по границе иногда оставляет висящий союз или предлог: описание
   кончается на «и», «et», «la», и в выдаче это читается как брак — Google
   дорисовывает многоточие к слову, после которого ничего нет. Срезаем такие
   хвосты вместе с пунктуацией. Список намеренно консервативный: лучше
   оставить лишнее слово, чем отрезать осмысленное. */
const DANGLING_TAIL = new RegExp(
  "(?:\\s|^)(?:" + [
    "and", "or", "with", "for", "from", "the", "of", "to", "in", "on", "at",
    "et", "ou", "avec", "pour", "depuis", "les", "le", "la", "des", "du", "de", "aux", "au",
    "y", "o", "con", "para", "desde", "los", "las", "el",
    "und", "oder", "mit", "fur", "von", "der", "die", "das", "den", "dem", "zu", "im",
    "\u0438", "\u0438\u043b\u0438", "\u0441", "\u0441\u043e", "\u0434\u043b\u044f", "\u043e\u0442", "\u0434\u043e", "\u043f\u043e",
    "\u043d\u0430", "\u0432", "\u0432\u043e", "\u0430", "\u043d\u043e", "\u043a", "\u0443", "\u0438\u0437",
  ].join("|") + ")$",
  "i",
);

function trimDanglingTail(text) {
  let out = String(text).replace(/[\s,;:\u2014\u2013]+$/, "");
  /* Повторяем: после «des» может открыться «et», и обрезать надо оба. */
  for (let i = 0; i < 3; i += 1) {
    const next = out.replace(DANGLING_TAIL, "").replace(/[\s,;:\u2014\u2013]+$/, "");
    if (next === out || !next) break;
    out = next;
  }
  return out;
}

function fitMetaDescription(text, locale) {
  const collapsed = String(text || "").replace(/\s+/g, " ").trim();
  const limit = metaDescriptionLimit(locale);
  if (!collapsed || collapsed.length <= limit) return collapsed;

  const boundaries = [/(?<=[.!?…])\s/g, /\s[—–:]\s/g, /,\s/g];
  for (const pattern of boundaries) {
    let best = null;
    for (const match of collapsed.matchAll(pattern)) {
      const end = match[0].startsWith(" ") ? match.index : match.index + 1;
      const candidate = trimDanglingTail(collapsed.slice(0, end));
      if (candidate.length <= limit && (!best || candidate.length > best.length)) best = candidate;
    }
    /* Слишком короткий кусок хуже длинного: если граница отрезала больше
       половины, пробуем следующую, более мелкую. */
    if (best && best.length >= limit * 0.55) return best;
  }
  const hard = collapsed.slice(0, limit + 1);
  const lastSpace = hard.lastIndexOf(" ");
  return trimDanglingTail(lastSpace > 0 ? hard.slice(0, lastSpace) : hard.slice(0, limit));
}

function localizedMainPageRoute(locale = "en") {
  return `/bali/${locale}/main-page`;
}

function localizedMainPageFileName(locale = "en") {
  return locale === "en" ? "page128073236.html" : `bali-main-page-${locale}.html`;
}

function localizedJournalHubRoute(locale = "en") {
  return `/bali/${locale}/journal`;
}

function localizedJournalHubFileName(locale = "en") {
  return locale === "en" ? "bali-journal.html" : `bali-journal-${locale}.html`;
}

/* Тот же принцип, что и в rewriteBaliLocaleRoutesInHtml: не подставляем язык
   в адрес страницы, которой нет. Отсюда шли ссылки в чипсах «наши PDF о Бали»
   и в шапке — по двадцать несуществующих немецких адресов на страницу тура. */
function localizedBaliInternalRoute(route, locale = "en") {
  const text = String(route || "");
  if (locale === "en") return text;
  const path = text.replace(new RegExp(`^${escapeRegExp(SITE_URL)}`, "i"), "");
  if (/^\/bali\/en(\/|$)/i.test(path) && !localeCoversRoute(path, locale)) return text;
  return text
    .replace(/^\/bali\/en(?=\/|$)/i, `/bali/${locale}`)
    .replace(new RegExp(`^${escapeRegExp(SITE_URL)}\\/bali\\/en(?=\\/|$)`, "i"), `${SITE_URL}/bali/${locale}`);
}

function localizedTourFileName(slug, locale = "en") {
  return locale === "en" ? `bali-tour-${slug}.html` : `bali-tour-${slug}-${locale}.html`;
}

function localizedJournalArticleFileName(tour, articleType, locale = "en") {
  const base = journalArticleFileName(tour, articleType).replace(/\.html$/i, "");
  return locale === "en" ? `${base}.html` : `${base}-${locale}.html`;
}

function localizedGuideArticleFileName(guide, locale = "en") {
  const base = guideArticleFileName(guide).replace(/\.html$/i, "");
  return locale === "en" ? `${base}.html` : `${base}-${locale}.html`;
}

function switchBaliRouteLocale(route, locale = "en") {
  const text = String(route || "");
  return text
    .replace(/^\/bali\/[a-z]{2}(?=\/|$|#)/i, `/bali/${locale}`)
    .replace(new RegExp(`^${escapeRegExp(SITE_URL)}\\/bali\\/[a-z]{2}(?=\\/|$|#)`, "i"), `${SITE_URL}/bali/${locale}`);
}

/* Перевод внутренних ссылок на язык страницы — с проверкой, что такая страница есть.

   Раньше здесь стояла слепая замена префикса: любой /bali/en/… превращался в
   /bali/<язык>/…, независимо от того, собрали мы эту страницу или нет. Для
   русского, испанского и французского это работало, потому что они полные.
   Немецкий раскатан волной на сто страниц из трёхсот семидесяти — и каждая
   ссылка на непокрытую статью превращалась в 404.

   Замер 24.08.2026: 1082 битые ссылки на 99 из 101 немецкой страницы, в среднем
   по десять на страницу. Плюс по 30 на четырёх страницах у ru/es/fr/zh — это
   статьи с неполным покрытием языков (теперь этим ведает GUIDE_LOCALES).
   Карта сайта и hreflang при этом были чистыми:
   там проверка через localeCoversRoute стояла, а здесь её не было.

   Цена не только в пользователе, который упирается в 404. Google идёт по этим
   ссылкам и тратит на них обход — тот самый, которого немецким страницам не
   хватает: на 24.08 из выборки в 12 адресов проиндексированы 3, а 5 роботу
   вообще неизвестны. Частичная раскатка экономила место в индексе и одновременно
   жгла обход на несуществующих адресах.

   Теперь маршрут проверяется целиком. Нет локализованной версии — ссылка
   остаётся английской: рабочая страница на чужом языке лучше, чем 404. */
/* Общая заготовка сообщения в WhatsApp приходит из исходной вёрстки Tilda,
   а не из генератора: она вшита в шапку и подвал готовым href. Через перевод
   такая строка не проходит нигде — на немецких страницах туров её оставалось
   108 штук по-английски, при живых пинах на все три формы апострофа.
   Раз строка статическая, подставляем её по языку прямо здесь: эта функция
   выполняется для КАЖДОЙ локализованной страницы, каким бы путём она ни
   собиралась. Порядок пар важен: сначала длинные, потом короткие. */
const STATIC_WHATSAPP_TEXTS = [
  {
    en: "Hello! I'm interested in your excursions. Could you help me with the booking details?",
    ru: "Здравствуйте! Меня интересуют ваши экскурсии. Подскажете детали бронирования?",
    es: "¡Hola! Me interesan sus excursiones. ¿Podrían ayudarme con los detalles de la reserva?",
    fr: "Bonjour ! Vos excursions m'intéressent. Pourriez-vous m'aider avec les détails de réservation ?",
    de: "Hallo! Ich interessiere mich für Ihre Ausflüge. Können Sie mir mit den Buchungsdetails helfen?",
    zh: "您好！我对你们的行程很感兴趣，能帮我了解预订细节吗？",
  },
  {
    en: "Hello! I want to book a Bali tour. Please send availability, the best options, and full details.",
    ru: "Здравствуйте! Хочу забронировать экскурсию на Бали. Пришлите, пожалуйста, свободные даты, лучшие варианты и все детали.",
    es: "¡Hola! Quiero reservar una excursión en Bali. Envíenme disponibilidad, las mejores opciones y todos los detalles.",
    fr: "Bonjour ! Je souhaite réserver une excursion à Bali. Merci de m'envoyer les disponibilités, les meilleures options et tous les détails.",
    de: "Hallo! Ich möchte einen Ausflug auf Bali buchen. Bitte senden Sie mir Verfügbarkeit, die besten Optionen und alle Details.",
    zh: "您好！我想预订巴厘岛的行程，请发送可预订日期、推荐方案和完整信息。",
  },
];

function localizeStaticWhatsAppTexts(html, locale) {
  if (locale === "en") return html;
  let out = String(html || "");
  for (const item of STATIC_WHATSAPP_TEXTS) {
    const target = item[locale];
    if (!target) continue;
    /* Апостроф в готовом HTML встречается в трёх видах: сырой, &#39; и &#039;.
       Кодируем каждый вариант отдельно, иначе совпадёт только один. */
    for (const raw of [item.en, item.en.replace(/'/g, "&#39;"), item.en.replace(/'/g, "&#039;")]) {
      const encoded = encodeURIComponent(raw).replace(/%26%2339%3B/g, "&#39;").replace(/%26%23039%3B/g, "&#039;");
      if (out.includes(encoded)) out = out.split(encoded).join(encodeURIComponent(target));
    }
  }
  return out;
}

function rewriteBaliLocaleRoutesInHtml(html, locale = "en") {
  html = localizeStaticWhatsAppTexts(html, locale);
  if (locale === "en") return html;
  const swapLocale = (whole, site, rest) => {
    const route = `/bali/en${rest || ""}`;
    if (!localeCoversRoute(route, locale)) return whole;
    return `${site || ""}/bali/${locale}${rest || ""}`;
  };
  return String(html || "")
    .replace(
      new RegExp(`(${escapeRegExp(SITE_URL)})?\\/bali\\/en((?:\\/[a-z0-9-]+)*)(?=$|["'#?\\s<])`, "g"),
      swapLocale,
    )
    // Планировщик берёт язык из адреса, а не из пути: /ai-planner?lang=xx
    .replace(/\/ai-planner\?lang=en\b/g, `/ai-planner?lang=${locale}`);
}

function protectHtmlBlocks(html) {
  const blocks = [];
  const protectedHtml = String(html || "").replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, (block) => {
    const token = `__SB_HTML_BLOCK_${blocks.length}__`;
    blocks.push(block);
    return token;
  });
  return { protectedHtml, blocks };
}

function restoreHtmlBlocks(html, blocks = []) {
  return String(html || "").replace(/__SB_HTML_BLOCK_(\d+)__/g, (_, rawIndex) => blocks[Number(rawIndex)] || "");
}

async function translateStandaloneHtmlVisibleText(html, locale = "en", options = {}) {
  if (locale === "en") return html;

  const { protectedHtml, blocks } = protectHtmlBlocks(html);
  const textValues = new Set();

  protectedHtml.replace(/>([^<>]+)</g, (_, rawText) => {
    const trimmed = String(rawText || "").replace(/\s+/g, " ").trim();
    if (shouldTranslateTextValue(trimmed)) {
      textValues.add(trimmed);
    }
    return _;
  });

  protectedHtml.replace(/<(?:title)>([^<]+)<\/title>/gi, (_, rawText) => {
    const trimmed = String(rawText || "").replace(/\s+/g, " ").trim();
    if (shouldTranslateTextValue(trimmed)) {
      textValues.add(trimmed);
    }
    return _;
  });

  protectedHtml.replace(
    /(<meta\b[^>]*\b(?:name|property)=["'](?:description|og:title|og:description|twitter:title|twitter:description)["'][^>]*\bcontent=["'])([^"']+)(["'][^>]*>)/gi,
    (_, __, rawText) => {
      const trimmed = String(rawText || "").replace(/\s+/g, " ").trim();
      if (shouldTranslateTextValue(trimmed)) {
        textValues.add(trimmed);
      }
      return _;
    },
  );

  protectedHtml.replace(/(\s(?:alt|title|placeholder|aria-label)=["'])([^"']+)(["'])/gi, (_, __, rawText) => {
    const trimmed = String(rawText || "").replace(/\s+/g, " ").trim();
    if (shouldTranslateTextValue(trimmed)) {
      textValues.add(trimmed);
    }
    return _;
  });

  /* Заготовка сообщения в WhatsApp лежит в адресе ссылки — дважды закодированная,
     сначала URL, потом HTML. Поэтому переводчик её не видел, и на французской
     странице первая же попытка забронировать открывала чат с английским
     текстом. При 86 показах и нуле кликов это прямая потеря, а не косметика. */
  for (const raw of collectWhatsAppTexts(protectedHtml)) {
    if (shouldTranslateTextValue(raw)) textValues.add(raw);
  }

  /* Тексты из разметки schema.org. Их надо собрать отдельно и до перевода:
     блоки ld+json к этому моменту уже замаскированы protectHtmlBlocks, поэтому
     в обычный сбор по видимому HTML они не попадают вовсе. А translateJsonLdValues
     ниже спрашивает перевод у той же карты — и не находит там строк, которых
     никто не просил.

     Из-за этого разметка переводилась только по случайному совпадению: когда
     ровно та же строка встречалась ещё и в видимом тексте. Где вёрстка режет
     текст на куски (легаси-страницы Tilda) или где описание в разметке своё,
     Google получал английский FAQ на французской странице. Молча: JSON валиден,
     сборка зелёная, видимый текст переведён. 763 страницы из 1561. */
  for (const raw of collectJsonLdTexts(html)) {
    if (shouldTranslateTextValue(raw)) textValues.add(raw);
  }

  const translationMap = await translateTextMap(Array.from(textValues), locale, { glossary: options.glossary || null });

  const translatePreservingWhitespace = (rawText) => {
    const source = String(rawText || "");
    const collapsed = source.replace(/\s+/g, " ").trim();
    if (!collapsed || !translationMap.has(collapsed)) {
      return source;
    }
    const translated = translationMap.get(collapsed) || collapsed;
    const leading = source.match(/^\s*/)?.[0] || "";
    const trailing = source.match(/\s*$/)?.[0] || "";
    return `${leading}${translated}${trailing}`;
  };

  let localizedHtml = protectedHtml
    .replace(/>([^<>]+)</g, (match, rawText) => `>${translatePreservingWhitespace(rawText)}<`)
    .replace(/<(?:title)>([^<]+)<\/title>/gi, (match, rawText) => `<title>${translatePreservingWhitespace(rawText).trim()}</title>`)
    .replace(
      /(<meta\b[^>]*\b(?:name|property)=["'](?:description|og:title|og:description|twitter:title|twitter:description)["'][^>]*\bcontent=["'])([^"']+)(["'][^>]*>)/gi,
      (match, prefix, rawText, suffix) => {
        const translated = translatePreservingWhitespace(rawText).trim();
        const isDescription = /(?:name|property)=["'](?:description|og:description|twitter:description)["']/i.test(match);
        return `${prefix}${isDescription ? fitMetaDescription(translated, locale) : translated}${suffix}`;
      },
    )
    .replace(
      /(\s(?:alt|title|placeholder|aria-label)=["'])([^"']+)(["'])/gi,
      (match, prefix, rawText, suffix) => `${prefix}${translatePreservingWhitespace(rawText).trim()}${suffix}`,
    );

  localizedHtml = restoreHtmlBlocks(localizedHtml, blocks);
  localizedHtml = localizedHtml.replace(/<html lang="[^"]+"/i, `<html lang="${locale}"`);
  localizedHtml = localizedHtml.replace(/("inLanguage"\s*:\s*")en(")/g, `$1${locale}$2`);
  localizedHtml = translateJsonLdValues(localizedHtml, translatePreservingWhitespace);
  localizedHtml = translateWhatsAppLinks(localizedHtml, translatePreservingWhitespace);
  return localizedHtml;
}


/* Перевод значений в JSON-LD.
 *
 * protectHtmlBlocks прячет ВСЕ <script>, включая application/ld+json, чтобы
 * перевод не разломал разметку. Побочный эффект был тихим и дорогим: у
 * французской страницы менялся только "inLanguage" на fr, а десять вопросов
 * FAQPage оставались английскими при десяти французских на самой странице —
 * пересечение нулевое. Разметка, не совпадающая с видимым текстом, права на
 * FAQ-сниппет не даёт.
 *
 * Новых запросов к переводчику здесь не возникает: строки в разметке те же
 * самые, что в видимом тексте, и лежат в уже собранном translationMap. Чего в
 * нём нет — остаётся английским, то есть хуже, чем было, не станет.
 *
 * Переводим только человекочитаемые поля. Имена типов schema.org, адреса,
 * идентификаторы и любые значения ключей с @ не трогаем: «FAQPage» на китайском
 * уже однажды превратилось в несуществующий тип и выбросило всю разметку. */
const JSON_LD_TEXT_KEYS = new Set([
  "name", "headline", "description", "text", "alternateName", "caption",
  "articleBody", "abstract", "disambiguatingDescription",
]);

/* Ключ расходится между двумя стадиями и молча срывает перевод.
   Сбор текста со страницы работает с HTML, поэтому в кэш попадает ключ
   с сущностями — «Ayung&#39;s», «Golf &amp; Resort», — а сюда значение
   приходит после JSON.parse, то есть с сырыми «'» и «&». Ключи не
   совпадают, перевод не находится, и в разметке остаётся английский при
   переведённом видимом тексте: страница по-французски, а FAQ, который
   читает Google, по-английски. Ошибка тихая — JSON валиден, сборка зелёная.

   Поэтому пробуем все формы записи. Порядок важен: амперсанд кодируем
   первым, иначе испортим сущности, которые сами начинаются с «&». */
function jsonLdKeyVariants(value) {
  const out = [value];
  const hasAmp = value.includes("&");
  const hasApos = value.includes("'");
  const amp = hasAmp ? value.replace(/&/g, "&amp;") : value;
  if (hasAmp) out.push(amp);
  if (hasApos) {
    /* Четыре формы, и все четыре реально встречаются в собранных страницах:
       &#39; в теле, &#039; в части легаси-вёрстки, &#x27; в мета-тегах. */
    for (const ent of ["&#39;", "&#039;", "&#x27;"]) {
      out.push(value.replace(/'/g, ent));
      if (hasAmp) out.push(amp.replace(/'/g, ent));
    }
  }
  return out;
}

function decodeJsonLdEntities(text) {
  return String(text)
    .replace(/&#0?39;|&#x27;/gi, "'")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, "&");
}

function translateJsonLdText(value, translate) {
  for (const variant of jsonLdKeyVariants(value)) {
    const translated = translate(variant);
    if (translated !== variant) return decodeJsonLdEntities(translated);
  }
  return value;
}

function translateJsonLdNode(node, translate) {
  if (Array.isArray(node)) return node.map((item) => translateJsonLdNode(item, translate));
  if (!node || typeof node !== "object") return node;
  const out = {};
  for (const [key, value] of Object.entries(node)) {
    if (typeof value === "string" && JSON_LD_TEXT_KEYS.has(key) && !NEVER_TRANSLATE.has(value)) {
      out[key] = translateJsonLdText(value, translate);
    } else {
      out[key] = translateJsonLdNode(value, translate);
    }
  }
  return out;
}

/* Собирает человекочитаемые строки из всех блоков ld+json страницы.
   Ключи те же, что переводит translateJsonLdNode, иначе собранное и
   запрошенное разойдутся. */
function collectJsonLdTexts(html) {
  const found = new Set();
  const walk = (node) => {
    if (Array.isArray(node)) return node.forEach(walk);
    if (!node || typeof node !== "object") return;
    for (const [key, value] of Object.entries(node)) {
      if (typeof value === "string" && JSON_LD_TEXT_KEYS.has(key) && !NEVER_TRANSLATE.has(value)) {
        const trimmed = value.replace(/\s+/g, " ").trim();
        if (trimmed) found.add(trimmed);
      } else {
        walk(value);
      }
    }
  };
  for (const m of String(html || "").matchAll(
    /<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi,
  )) {
    try {
      walk(JSON.parse(m[1]));
    } catch {
      /* Битую разметку пропускаем: пусть её чинит тот, кто сломал. */
    }
  }
  return found;
}

function translateJsonLdValues(html, translate) {
  return String(html || "").replace(
    /(<script\b[^>]*type=["']application\/ld\+json["'][^>]*>)([\s\S]*?)(<\/script>)/gi,
    (whole, open, body, close) => {
      let data;
      try {
        data = JSON.parse(body);
      } catch {
        /* Битый JSON оставляем как есть: пусть его ловит тот, кто его сломал,
           а не молчаливая подмена на пустую разметку. */
        return whole;
      }
      return `${open}${JSON.stringify(translateJsonLdNode(data, translate))}${close}`;
    },
  );
}

/* Тексты заготовок WhatsApp из адресов ссылок.
   Кодировка двойная: HTML поверх URL, поэтому и разбирать надо в два шага. */
function decodeWhatsAppText(encoded) {
  try {
    return decodeURIComponent(String(encoded || "").replace(/&#0?39;/g, "'").replace(/&amp;/g, "&"));
  } catch {
    return "";
  }
}

function collectWhatsAppTexts(html) {
  const found = new Set();
  for (const m of String(html || "").matchAll(/wa\.me\/\d+\?text=([^"'\s<>]+)/g)) {
    const text = decodeWhatsAppText(m[1]).replace(/\s+/g, " ").trim();
    if (text) found.add(text);
  }
  return found;
}

function translateWhatsAppLinks(html, translate) {
  return String(html || "").replace(/(wa\.me\/\d+\?text=)([^"'\s<>]+)/g, (whole, prefix, encoded) => {
    const source = decodeWhatsAppText(encoded).replace(/\s+/g, " ").trim();
    if (!source) return whole;
    const translated = translate(source).trim();
    if (!translated || translated === source) return whole;
    return `${prefix}${encodeURIComponent(translated).replace(/'/g, "&#39;")}`;
  });
}

function renderJournalLanguageSwitcherMarkup(locale = "en", currentRoute = localizedJournalHubRoute(locale), variant = "desktop") {
  const routes = BALI_LANGUAGE_OPTIONS.filter((item) => localeCoversRoute(currentRoute, item.code)).map((item) => ({
    ...item,
    href: switchBaliRouteLocale(currentRoute, item.code),
    active: item.code === locale,
  }));
  /* Чёрная иконка в обоих вариантах. Белая версия предназначена для шапки
     поверх тёмного фото — так стоит на страницах туров, и там она верна. Но
     мобильная шапка журнала до скролла прозрачна, а страницы журнала светлые:
     белый глобус там был белым по белому, как и логотип рядом. При скролле
     шапка темнеет, и правило brightness(0) invert(1) красит иконку в белую
     само — тому состоянию исходный цвет безразличен. */
  const iconPath = "/images/ui/language-black.png";

  return `<details class="sb-journal-lang-switcher sb-journal-lang-switcher--${variant}">
    <summary class="sb-journal-lang-switcher__summary" aria-label="${escapeHtml(sharedBaliUiLabels(locale).languageSwitcherLabel)}">
      <img src="${iconPath}" alt="${escapeHtml(sharedBaliUiLabels(locale).languageSwitcherLabel)}">
    </summary>
    <div class="sb-journal-lang-switcher__menu">
      ${routes
        .map(
          (item) => `<a class="sb-journal-lang-switcher__option" data-active="${item.active ? "true" : "false"}" href="${escapeHtml(item.href)}">
            <span>${escapeHtml(item.label)}</span>
            <span class="sb-journal-lang-switcher__code">${escapeHtml(item.code.toUpperCase())}</span>
          </a>`,
        )
        .join("")}
    </div>
  </details>`;
}

function buildJournalLanguageSwitcherAssets() {
  return `
<style id="sb-journal-language-switcher-style">
.sb-journal-lang-switcher{position:relative;display:inline-flex;align-items:center}
.sb-journal-lang-switcher__summary{list-style:none;display:inline-flex;align-items:center;justify-content:center;width:42px;height:42px;padding:0;border:0;background:transparent;cursor:pointer}
.sb-journal-lang-switcher__summary::-webkit-details-marker{display:none}
.sb-journal-lang-switcher__summary img{width:28px;height:28px;object-fit:contain;display:block}
.sb-journal-lang-switcher__menu{position:absolute;top:calc(100% + 10px);right:0;display:none;min-width:190px;padding:10px;border-radius:18px;background:#fff;box-shadow:0 18px 46px rgba(17,24,39,0.18);z-index:1006}
.sb-journal-lang-switcher[open] .sb-journal-lang-switcher__menu{display:grid;gap:6px}
.sb-journal-lang-switcher__option{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:42px;padding:10px 14px;border-radius:14px;background:rgba(126,196,244,0.08);color:#111827;font-family:'Cina GEO', 'TildaSans',Arial,sans-serif;font-size:15px;line-height:1.2;font-weight:600;text-decoration:none}
.sb-journal-lang-switcher__option:hover,.sb-journal-lang-switcher__option:focus-visible{background:rgba(126,196,244,0.16);outline:none}
.sb-journal-lang-switcher__option[data-active="true"]{background:rgba(126,196,244,0.24);color:#0f172a}
.sb-journal-lang-switcher__code{font-size:12px;line-height:1;font-weight:700;letter-spacing:.08em;text-transform:uppercase;opacity:.6}
.sb-journal-tour-header__langs{display:flex;align-items:center;gap:12px;color:#000;font-size:16px;font-weight:600;letter-spacing:-1px}
.sb-journal-tour-header__mobile-bar{grid-template-columns:1fr auto auto !important}
.sb-journal-tour-header__mobile-logo-link{order:1;justify-self:start}
.sb-journal-tour-header__socials{order:2;justify-self:end}
.sb-journal-tour-header__burger{order:3;justify-self:end}
.sb-journal-tour-header__socials{display:flex;align-items:center;gap:10px;justify-content:flex-end}
.sb-journal-tour-header__socials .sb-journal-lang-switcher__summary{width:30px;height:30px}
.sb-journal-tour-header__socials .sb-journal-lang-switcher__summary img{width:26px;height:26px}
.sb-journal-tour-header__socials .sb-journal-lang-switcher__menu{background:#3a3a3a;box-shadow:0 18px 46px rgba(17,24,39,0.28)}
.sb-journal-tour-header__socials .sb-journal-lang-switcher__option{background:rgba(255,255,255,0.08);color:#fff}
.sb-journal-tour-header__socials .sb-journal-lang-switcher__option:hover,.sb-journal-tour-header__socials .sb-journal-lang-switcher__option:focus-visible{background:rgba(255,255,255,0.14)}
.sb-journal-tour-header__socials .sb-journal-lang-switcher__option[data-active="true"]{background:rgba(126,196,244,0.16);color:#7ec4f4}
@media screen and (max-width:640px){.sb-journal-lang-switcher__menu{min-width:174px}}
</style>`;
}

function localizeJournalShell(html, locale = "en", currentRoute = localizedJournalHubRoute(locale)) {
  let localizedHtml = html.replace(/<html lang="[^"]+"/i, `<html lang="${locale}"`);
  const assets = buildJournalLanguageSwitcherAssets();
  if (!localizedHtml.includes('id="sb-journal-language-switcher-style"') && /<\/head>/i.test(localizedHtml)) {
    localizedHtml = localizedHtml.replace(/<\/head>/i, `${assets}\n</head>`);
  }

  localizedHtml = rewriteBaliLocaleRoutesInHtml(localizedHtml, locale);

  localizedHtml = localizedHtml.replace(
    /<div class="sb-journal-tour-header__langs"[\s\S]*?<\/div>/,
    `<div class="sb-journal-tour-header__langs">${renderJournalLanguageSwitcherMarkup(locale, currentRoute, "desktop")}</div>`,
  );

  localizedHtml = localizedHtml.replace(
    /<div class="sb-journal-tour-header__socials"[\s\S]*?<\/div>/,
    `<div class="sb-journal-tour-header__socials" aria-label="Language selector">${renderJournalLanguageSwitcherMarkup(locale, currentRoute, "mobile")}</div>`,
  );

  return localizedHtml;
}

async function buildLocalizedStaticHtmlPage(html, locale = "en", options = {}) {
  if (locale === "en") return html;

  const {
    shell = "generic",
    currentRoute = localizedMainPageRoute(locale),
    routeBuilder,
  } = options;

  /* Сёрф-глоссарий включаем по адресу страницы, а не по содержимому.
     Сторож «есть ли в сегменте сёрф-слово» не работает: сегменты короткие,
     и в «Страна грез — единственный перерыв с песчаным дном» нет ни одного
     слова из списка. А по маршруту мы знаем тему точно — и соседние темы
     (храмы, детские площадки, обеденный перерыв) вообще вне зоны риска. */
  const route = String(currentRoute || "");
  const glossary = SURF_GLOSSARY_ROUTES.test(route) ? "surf"
    : PLACES_GLOSSARY_ROUTES.test(route) ? "places"
    : null;

  let localizedHtml = String(html || "");

  if (shell === "tilda") {
    localizedHtml = localizeUnescoShell(localizedHtml, locale, {
      routeBuilder: typeof routeBuilder === "function" ? routeBuilder : (code) => switchBaliRouteLocale(currentRoute, code),
    });
  } else if (shell === "journal") {
    localizedHtml = localizeJournalShell(localizedHtml, locale, currentRoute);
  }

  localizedHtml = rewriteBaliLocaleRoutesInHtml(localizedHtml, locale);
  localizedHtml = await translateStandaloneHtmlVisibleText(localizedHtml, locale, { glossary });
  localizedHtml = rewriteBaliLocaleRoutesInHtml(localizedHtml, locale);

  if (shell === "tilda") {
    localizedHtml = localizeUnescoShell(localizedHtml, locale, {
      routeBuilder: typeof routeBuilder === "function" ? routeBuilder : (code) => switchBaliRouteLocale(currentRoute, code),
    });
  } else if (shell === "journal") {
    localizedHtml = localizeJournalShell(localizedHtml, locale, currentRoute);
  }

  localizedHtml = localizedHtml.replace(/<html lang="[^"]+"/i, `<html lang="${locale}"`);
  localizedHtml = localizedHtml.replace(new RegExp(`(<link rel="canonical" href=")${SITE_URL_RE}/bali/en`, "gi"), `$1${SITE_URL}/bali/${locale}`);
  localizedHtml = localizedHtml.replace(new RegExp(`(<meta property="og:url" content=")${SITE_URL_RE}/bali/en`, "gi"), `$1${SITE_URL}/bali/${locale}`);
  localizedHtml = localizedHtml.replace(/("inLanguage"\s*:\s*")en(")/g, `$1${locale}$2`);
  return localizedHtml;
}

function buildLocalizedUnescoTour(locale = "en") {
  const baseTour = tourBySlug("bali-unesco");
  if (!baseTour) return null;
  if (locale === "en") {
    return {
      ...baseTour,
      locale: "en",
    };
  }

  const translation = UNESCO_PAGE_TRANSLATIONS[locale];
  if (!translation) return null;

  return {
    ...baseTour,
    ...translation,
    locale,
    mainPage: false,
    aiPlanner: false,
    tags: Array.isArray(baseTour.tags) ? [...baseTour.tags] : [],
    related: Array.isArray(baseTour.related) ? [...baseTour.related] : [],
    collageImages: Array.isArray(baseTour.collageImages) ? baseTour.collageImages.map((asset) => ({ ...asset })) : [],
    mainPageFeatures: Array.isArray(baseTour.mainPageFeatures) ? baseTour.mainPageFeatures.map((feature) => [...feature]) : [],
    highlights: translation.highlights.map((item) => [...item]),
    itinerary: translation.itinerary.map((item) => [...item]),
    includes: [...translation.includes],
    goodToKnow: [...translation.goodToKnow],
    faqs: translation.faqs.map((item) => [...item]),
    reviews: translation.reviews.map((item) => ({ ...item })),
  };
}

function collectAutoTourTranslations(tour) {
  const plain = new Set();
  const rich = new Set();
  const addPlain = (value) => {
    if (shouldTranslateTextValue(value)) plain.add(String(value));
  };
  const addRich = (value) => {
    if (shouldTranslateTextValue(value)) rich.add(String(value));
  };

  [
    tour.title,
    tour.metaTitle,
    tour.metaDescription,
    tour.eyebrow,
    tour.duration,
    tour.pickup,
    tour.bestFor,
    tour.format,
    tour.area,
    tour.compactAreaLabel,
    tour.imageAlt,
    tour.lead,
    tour.summary,
    tour.overview,
    tour.aboutSubtitle,
    tour.meetingPoint,
    tour.whatsappText,
    tour.privateOfferEyebrow,
    tour.privateOfferTopline,
    tour.mapLabel,
    tour.mapTitle,
    tour.mapText,
    tour.miniPromoText,
    tour.miniPromoEyebrow,
    tour.miniPromoSideText,
    tour.ctaLabel,
    tour.faqIntro,
    tour.breadcrumbHome,
    tour.breadcrumbTours,
    tour.price,
    tour.mainPagePrice,
    tour.mainPagePriceNote,
    tour.offerSectionHeading,
  ].forEach(addPlain);

  [tour.fullDescriptionKeyStopsHtml, tour.fullDescriptionBestFitHtml].forEach(addRich);

  (tour.highlights || []).forEach(([title, text]) => {
    addPlain(title);
    addPlain(text);
  });

  (tour.itinerary || []).forEach(([title, text]) => {
    addPlain(title);
    addPlain(text);
  });

  (tour.includes || []).forEach(addPlain);
  (tour.goodToKnow || []).forEach(addPlain);
  (tour.faqs || []).forEach(([question, answer]) => {
    addPlain(question);
    addPlain(answer);
  });
  // Полностью собранный FAQ (включая авто-сгенерированные вопросы) — переводим
  // целыми строками, чтобы на не-EN страницах не оставался английский каркас.
  buildWestFaqs(tour).forEach(([question, answer]) => {
    addPlain(question);
    addPlain(answer);
  });
  // Отзывы (включая авто-сгенерированные) — переводим целыми строками,
  // иначе на не-EN страницах остаются английские тексты и даты.
  buildWestReviews(tour).forEach((review) => {
    addPlain(review.text);
    addPlain(review.title);
    addPlain(review.date);
  });
  // Синтезированные includes/goodToKnow тоже переводим целыми строками
  buildIncludes(tour).forEach(addPlain);
  buildGoodToKnow(tour).forEach(addPlain);
  (tour.reviews || []).forEach((review) => {
    addPlain(review?.text);
    addPlain(review?.title);
    addPlain(review?.date);
  });
  (tour.mainPageFeatures || []).forEach((feature) => addPlain(feature?.[1]));
  (tour.collageImages || []).forEach((asset) => addPlain(asset?.altText));

  return {
    plain: Array.from(plain),
    rich: Array.from(rich),
  };
}

function withTranslatedText(value, map) {
  if (!value || !(map instanceof Map)) return value;
  return map.get(String(value)) || value;
}

async function buildAutoLocalizedTour(baseTour, locale = "en") {
  if (!baseTour) return null;
  if (baseTour.slug === "bali-unesco") {
    return buildLocalizedUnescoTour(locale);
  }
  if (locale === "en") {
    return {
      ...baseTour,
      locale: "en",
      ui: sharedBaliUiLabels("en"),
    };
  }

  const strings = collectAutoTourTranslations(baseTour);
  const plainMap = await translateTextMap(strings.plain, locale);
  const richMap = await translateTextMap(strings.rich, locale, { richText: true });

  const translatedTour = {
    ...baseTour,
    locale,
    ui: sharedBaliUiLabels(locale),
    mainPage: false,
    aiPlanner: false,
    title: withTranslatedText(baseTour.title, plainMap),
    metaTitle: withTranslatedText(baseTour.metaTitle, plainMap),
    /* Описание тура тоже подгоняем: путь у туровых страниц свой, через
       общий фильтр мета-тегов они не проходят. */
    metaDescription: fitMetaDescription(withTranslatedText(baseTour.metaDescription, plainMap), locale),
    eyebrow: withTranslatedText(baseTour.eyebrow, plainMap),
    duration: withTranslatedText(baseTour.duration, plainMap),
    pickup: withTranslatedText(baseTour.pickup, plainMap),
    bestFor: withTranslatedText(baseTour.bestFor, plainMap),
    format: withTranslatedText(baseTour.format, plainMap),
    area: withTranslatedText(baseTour.area, plainMap),
    compactAreaLabel: withTranslatedText(baseTour.compactAreaLabel, plainMap),
    imageAlt: withTranslatedText(baseTour.imageAlt, plainMap),
    lead: withTranslatedText(baseTour.lead, plainMap),
    summary: withTranslatedText(baseTour.summary, plainMap),
    overview: withTranslatedText(baseTour.overview, plainMap),
    aboutSubtitle: withTranslatedText(baseTour.aboutSubtitle, plainMap),
    meetingPoint: withTranslatedText(baseTour.meetingPoint, plainMap),
    whatsappText: withTranslatedText(baseTour.whatsappText, plainMap),
    privateOfferEyebrow: withTranslatedText(baseTour.privateOfferEyebrow, plainMap),
    privateOfferTopline: withTranslatedText(baseTour.privateOfferTopline, plainMap),
    mapLabel: withTranslatedText(baseTour.mapLabel, plainMap),
    mapTitle: withTranslatedText(baseTour.mapTitle, plainMap),
    mapText: withTranslatedText(baseTour.mapText, plainMap),
    miniPromoText: withTranslatedText(baseTour.miniPromoText, plainMap),
    miniPromoEyebrow: withTranslatedText(baseTour.miniPromoEyebrow, plainMap),
    miniPromoSideText: withTranslatedText(baseTour.miniPromoSideText, plainMap),
    ctaLabel: withTranslatedText(baseTour.ctaLabel, plainMap),
    faqIntro: withTranslatedText(baseTour.faqIntro, plainMap),
    breadcrumbHome: withTranslatedText(baseTour.breadcrumbHome, plainMap),
    breadcrumbTours: withTranslatedText(baseTour.breadcrumbTours, plainMap),
    price: withTranslatedText(baseTour.price, plainMap),
    priceSource: baseTour.priceSource || baseTour.price,   // для разметки: цена не зависит от языка
    mainPagePrice: withTranslatedText(baseTour.mainPagePrice, plainMap),
    mainPagePriceNote: withTranslatedText(baseTour.mainPagePriceNote, plainMap),
    offerSectionHeading: withTranslatedText(baseTour.offerSectionHeading, plainMap),
    fullDescriptionKeyStopsHtml: withTranslatedText(baseTour.fullDescriptionKeyStopsHtml, richMap),
    fullDescriptionBestFitHtml: withTranslatedText(baseTour.fullDescriptionBestFitHtml, richMap),
    highlights: (baseTour.highlights || []).map(([title, text]) => [withTranslatedText(title, plainMap), withTranslatedText(text, plainMap)]),
    itinerary: (baseTour.itinerary || []).map(([title, text]) => [withTranslatedText(title, plainMap), withTranslatedText(text, plainMap)]),
    includes: buildIncludes(baseTour).map((item) => withTranslatedText(item, plainMap)),
    goodToKnow: buildGoodToKnow(baseTour).map((item) => withTranslatedText(item, plainMap)),
    faqs: buildWestFaqs(baseTour).map(([question, answer]) => [withTranslatedText(question, plainMap), withTranslatedText(answer, plainMap)]),
    reviews: (baseTour.reviews?.length ? baseTour.reviews : buildWestReviews(baseTour)).map((review) => ({
      ...review,
      text: withTranslatedText(review?.text, plainMap),
      title: withTranslatedText(review?.title, plainMap),
      date: withTranslatedText(review?.date, plainMap),
    })),
    mainPageFeatures: (baseTour.mainPageFeatures || []).map(([icon, text]) => [icon, withTranslatedText(text, plainMap)]),
    collageImages: (baseTour.collageImages || []).map((asset) =>
      asset && typeof asset === "object"
        ? {
            ...asset,
            altText: withTranslatedText(asset.altText, plainMap),
          }
        : asset,
    ),
    related: Array.isArray(baseTour.related) ? [...baseTour.related] : [],
    tags: Array.isArray(baseTour.tags) ? [...baseTour.tags] : [],
    mainPageFilterTags: Array.isArray(baseTour.mainPageFilterTags) ? [...baseTour.mainPageFilterTags] : baseTour.mainPageFilterTags,
  };

  return translatedTour;
}

